#include <algorithm>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("pairup.in");
    std::ofstream out("pairup.out");
    int n;
    in >> n;
    std::vector<std::pair<long long, long long>> groups(n);
    for (auto &group : groups) in >> group.second >> group.first;
    std::sort(groups.begin(), groups.end());
    int left = 0, right = n - 1;
    long long answer = 0;
    while (left <= right) {
        while (left <= right && groups[left].second == 0) ++left;
        while (left <= right && groups[right].second == 0) --right;
        if (left > right) break;
        if (left == right) {
            if (groups[left].second >= 2)
                answer = std::max(answer, 2 * groups[left].first);
            break;
        }
        const long long take = std::min(groups[left].second, groups[right].second);
        answer = std::max(answer, groups[left].first + groups[right].first);
        groups[left].second -= take;
        groups[right].second -= take;
    }
    out << answer << '\n';
}
