#include <array>
#include <fstream>
#include <string>
#include <vector>
int nucleotide(char c) {
    if (c == 'A') return 0;
    if (c == 'C') return 1;
    if (c == 'G') return 2;
    return 3;
}
int main() {
    std::ifstream in("cownomics.in");
    std::ofstream out("cownomics.out");
    int n, m;
    in >> n >> m;
    std::vector<std::string> spotted(n), plain(n);
    for (auto &genome : spotted) in >> genome;
    for (auto &genome : plain) in >> genome;
    int answer = 0;
    for (int i = 0; i < m; ++i)
        for (int j = i + 1; j < m; ++j)
            for (int k = j + 1; k < m; ++k) {
                std::array<bool, 64> present{};
                for (const auto &genome : spotted) {
                    const int code = 16 * nucleotide(genome[i])
                        + 4 * nucleotide(genome[j]) + nucleotide(genome[k]);
                    present[code] = true;
                }
                bool valid = true;
                for (const auto &genome : plain) {
                    const int code = 16 * nucleotide(genome[i])
                        + 4 * nucleotide(genome[j]) + nucleotide(genome[k]);
                    if (present[code]) { valid = false; break; }
                }
                if (valid) ++answer;
            }
    out << answer << '\n';
}
