#include <array>
#include <fstream>
#include <string>
#include <vector>
class RectangleCounter {
    int n;
    const std::vector<std::string> &grid;
    std::vector<unsigned char> containsCandidate;
    int index(int top, int bottom, int left, int right) const {
        return ((top * n + bottom) * n + left) * n + right;
    }
    bool qualifies(int top, int bottom, int left, int right) const {
        std::vector<unsigned char> visited(n * n, 0);
        std::array<int, 26> components{};
        int colors = 0;
        const std::array<int, 4> dr{-1, 1, 0, 0}, dc{0, 0, -1, 1};
        std::vector<int> queue;
        for (int r = top; r <= bottom; ++r)
            for (int c = left; c <= right; ++c) {
                if (visited[r * n + c]) continue;
                const int color = grid[r][c] - 'A';
                if (components[color] == 0 && ++colors > 2) return false;
                ++components[color];
                queue.clear(); queue.push_back(r * n + c);
                visited[r * n + c] = 1;
                for (std::size_t head = 0; head < queue.size(); ++head) {
                    const int row = queue[head] / n, col = queue[head] % n;
                    for (int d = 0; d < 4; ++d) {
                        const int rr = row + dr[d], cc = col + dc[d];
                        if (rr < top || rr > bottom || cc < left || cc > right) continue;
                        const int cell = rr * n + cc;
                        if (!visited[cell] && grid[rr][cc] == grid[row][col]) {
                            visited[cell] = 1; queue.push_back(cell);
                        }
                    }
                }
            }
        if (colors != 2) return false;
        int single = 0, multiple = 0;
        for (int count : components) {
            if (count == 1) ++single;
            else if (count >= 2) ++multiple;
        }
        return single == 1 && multiple == 1;
    }
public:
    explicit RectangleCounter(const std::vector<std::string> &image)
        : n(static_cast<int>(image.size())), grid(image), containsCandidate(n * n * n * n, 0) {}
    int count() {
        int answer = 0;
        for (int height = n; height >= 1; --height)
            for (int width = n; width >= 1; --width)
                for (int top = 0; top + height <= n; ++top)
                    for (int left = 0; left + width <= n; ++left) {
                        const int bottom = top + height - 1, right = left + width - 1;
                        bool larger = false;
                        if (top > 0) larger |= containsCandidate[index(top - 1, bottom, left, right)] != 0;
                        if (bottom + 1 < n) larger |= containsCandidate[index(top, bottom + 1, left, right)] != 0;
                        if (left > 0) larger |= containsCandidate[index(top, bottom, left - 1, right)] != 0;
                        if (right + 1 < n) larger |= containsCandidate[index(top, bottom, left, right + 1)] != 0;
                        const bool good = qualifies(top, bottom, left, right);
                        if (good && !larger) ++answer;
                        containsCandidate[index(top, bottom, left, right)] = good || larger;
                    }
        return answer;
    }
};
int main() {
    std::ifstream in("where.in");
    std::ofstream out("where.out");
    int n;
    in >> n;
    std::vector<std::string> image(n);
    for (auto &row : image) in >> row;
    out << RectangleCounter(image).count() << '\n';
}
